cat > src/lib/selection.ts <<'EOF'
// Image selection caps: max 2 landscape, 1 portrait (fixed requirement)
export function canAdd(selected: {portrait: boolean}[], next: {portrait: boolean}): boolean {
  const portraits = selected.filter(s => s.portrait).length;
  if (next.portrait) return portraits < 1;
  return selected.length - portraits < 2;
}
EOF
cat > tests/selection.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert';
import { canAdd } from '../src/lib/selection.ts';

const portrait = { portrait: true };
const landscape = { portrait: false };

test('allows up to 2 landscape', () => {
  assert.ok(canAdd([], landscape));
  assert.ok(canAdd([landscape], landscape));
  assert.ok(!canAdd([landscape, landscape], landscape));
});

test('allows only 1 portrait', () => {
  assert.ok(canAdd([], portrait));
  assert.ok(!canAdd([portrait], portrait));
});

test('caps are independent', () => {
  assert.ok(canAdd([landscape, landscape], portrait));
  assert.ok(canAdd([portrait], landscape));
  assert.ok(!canAdd([portrait, landscape, landscape], landscape));
});
EOF
npm test 2>&1 | tail -20

